async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  let normalEOF = false;

  try {
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });
    const parts = [];
    let state = initial;
    let physicalLine = 1;
    let recordIndex = 0;

    async function processLine(line) {
      if (line.trim() === "") return false;

      let value;
      try {
        value = JSON.parse(line);
      } catch {
        return false;
      }

      const result = await reduce(state, value, {
        physicalLine,
        recordIndex: recordIndex++
      });
      state = result.state;
      return result.done === true;
    }

    while (true) {
      const step = await iterator.next();
      if (step.done) break;

      const chunk = step.value;
      let start = 0;

      for (let i = 0; i < chunk.length; i++) {
        if (chunk[i] !== 10) continue;

        const text = decoder.decode(chunk.subarray(start, i), {
          stream: true
        });
        if (text !== "") parts.push(text);

        const line = parts.join("");
        parts.length = 0;

        if (await processLine(line)) return state;

        physicalLine++;
        start = i + 1;
      }

      if (start < chunk.length) {
        const text = decoder.decode(chunk.subarray(start), {
          stream: true
        });
        if (text !== "") parts.push(text);
      }
    }

    const tail = decoder.decode();
    if (tail !== "") parts.push(tail);

    if (parts.length > 0) {
      const line = parts.join("");
      parts.length = 0;
      await processLine(line);
    }

    normalEOF = true;
    return state;
  } finally {
    if (!normalEOF) {
      const close = iterator.return;
      if (typeof close === "function") {
        await close.call(iterator);
      }
    }
  }
}
